
(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const records={"tv": {"k": "1 ШИРХЭГ", "title": "Haier QLED 55″", "copy": "55 инч · QLED · 4K · Google TV"}, "giftcard": {"k": "2 ШИРХЭГ", "title": "500,000₮-ийн бэлгийн карт", "copy": "SmartStore.mn-д ашиглах 500,000₮-ийн бэлгийн карт."}, "gold": {"k": "1 ШИРХЭГ", "title": "FineGoldNation", "copy": "FineGoldNation бэлгийн багц."}, "air": {"k": "2 ШИРХЭГ", "title": "Агаар цэвэршүүлэгч", "copy": "Sharp FPJ30LA."}, "watch": {"k": "2 ШИРХЭГ", "title": "Ухаалаг цаг", "copy": "Xiaomi Smart Band. Загварыг эцэслэн баталгаажуулна."}, "earbuds": {"k": "5 ШИРХЭГ", "title": "Утасгүй чихэвч", "copy": "Airmars XKT15."}, "shopping": {"k": "5 ШИРХЭГ", "title": "100,000₮-ийн эрх", "copy": "WoowPay мерчантаас худалдан авалт хийх эрх."}, "loan": {"k": "10 ШИРХЭГ", "title": "Зээл хаах эрх", "copy": "Идэвхтэй худалдан авалтын нэг зээлд хамаарна. Хамрах дүн, нөхцөлийг лавлаарай."}, "entries": {"k": "МИНИЙ ЭРХ", "title": "Эрхээ шалгах", "copy": "WoowPay-ийн Messenger чатботоор Супер сугалааны эрх болон Урамшууллын хүрд эргүүлэх эрхээ шалгаарай.", "href": "https://m.me/woowpay", "action": "Messenger-ээр шалгах ↗"}, "conditions": {"k": "СУГАЛАА", "title": "Оролцох нөхцөл", "copy": "WoowPay аппад бүртгүүлэхэд, мөн худалдан авалт хийх бүрд хүрд эргүүлэх эрхтэй болно. Хүрднээс Супер сугалааны эрх хожвол тохиролд оролцоно.\n\nОролцох эцсийн хугацаа болон бусад дэлгэрэнгүй нөхцөлийг удахгүй мэдээлнэ."}};
const dialog=$('#details-dialog');let opener;
function openDetails(key,source){const record=records[key];if(!record)return;opener=source;$('#dialog-kicker').textContent=record.k;$('#dialog-title').textContent=record.title;$('#dialog-copy').textContent=record.copy;const link=$('#dialog-link');link.href=record.href||'tel:72726565';$('#dialog-link-label').textContent=record.action||'7272 6565 · Лавлах';$('#dialog-messenger-icon').toggleAttribute('hidden',key!=='entries');if(record.href){link.target='_blank';link.rel='noopener'}else{link.removeAttribute('target');link.removeAttribute('rel')}dialog.showModal();document.body.classList.add('modal-open')}
$$('[data-prize],[data-dialog]').forEach(b=>b.addEventListener('click',()=>openDetails(b.dataset.prize||b.dataset.dialog,b)));
$('.modal-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');opener?.focus()});
const menu=$('.menu-toggle'),nav=$('#navigation');function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Цэс нээх');nav.classList.remove('is-open')};menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(expanded));menu.setAttribute('aria-label',expanded?'Цэс хаах':'Цэс нээх');nav.classList.toggle('is-open',expanded)});$$('#navigation a, #navigation button').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.nav'))closeMenu()});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let manuallyPaused=false;const motionButton=$('#motion-toggle');
function syncMotion(){const paused=manuallyPaused||reduced.matches;document.documentElement.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'▶':'Ⅱ';const label=paused?'Хөдөлгөөн үргэлжлүүлэх':'Хөдөлгөөн зогсоох';motionButton.setAttribute('aria-label',label);motionButton.title=label;motionButton.hidden=reduced.matches;motionButton.disabled=reduced.matches}
motionButton.addEventListener('click',()=>{manuallyPaused=!manuallyPaused;syncMotion()});reduced.addEventListener('change',syncMotion);syncMotion();
// Confirmed draw: December 25, 2026 at 13:00 in Ulaanbaatar (UTC+08:00).
const countdownTarget=Date.parse('2026-12-25T13:00:00+08:00');
const drawDayEnd=Date.parse('2026-12-26T00:00:00+08:00');
function updateCountdown(){const now=Date.now();let seconds=Math.max(0,Math.ceil((countdownTarget-now)/1000));$('.launch-clock').style.setProperty('--tick-fill',String((seconds%60)/60*100)+'%');const values=[Math.floor(seconds/86400),Math.floor(seconds%86400/3600),Math.floor(seconds%3600/60),seconds%60];['days','hours','minutes','seconds'].forEach((name,i)=>{const el=$('#clock-'+name),next=String(values[i]).padStart(2,'0');if(el.textContent!==next){const old=el.textContent;el.textContent=next;if(old!=='--'&&!reduced.matches&&!manuallyPaused){el.getAnimations().forEach(a=>a.cancel());el.animate([{transform:'translateY(-5px)',opacity:.45},{transform:'translateY(0)',opacity:1}],{duration:260,easing:'ease-out'})}}});if(now>=countdownTarget){$('#draw-results').hidden=false;$('.launch-clock').setAttribute('aria-label','Тохирлын цаг болсон');$('#countdown-title').textContent=now<drawDayEnd?'Тохирлын цаг боллоо!':'Тохирлын мэдээлэл';} }
updateCountdown();setInterval(updateCountdown,1000);
document.documentElement.classList.add('js-ready');
})();
